CREATE TABLE `rotation_policies` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text NOT NULL,`description` text,`scope` text NOT NULL DEFAULT "environment",`project_id` integer,`environment_id` integer,`interval_days` integer NOT NULL,`alert_days_before` integer NOT NULL DEFAULT 7,`notify_on_breach` numeric NOT NULL DEFAULT true,`is_active` numeric NOT NULL DEFAULT true,`created_by` text NOT NULL,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`rotation_state` text DEFAULT "idle",`last_rotation_error` text DEFAULT "",`last_state_at` datetime);
